(function () {
  // ── shared helpers (SVG, tweening) ─────────────────────────────────────────
  var NS = "http://www.w3.org/2000/svg";
  var svg = document.getElementById("scene");
  var labelEl = document.getElementById("step-label");
  var captionEl = document.getElementById("caption");

  function el(name, attrs, parent) {
    var node = document.createElementNS(NS, name);
    for (var key in attrs) node.setAttribute(key, attrs[key]);
    if (parent) parent.appendChild(node);
    return node;
  }
  function txt(parent, x, y, cls, str, anchor) {
    var t = el("text", { x: x, y: y, class: cls }, parent);
    if (anchor) t.setAttribute("text-anchor", anchor);
    t.textContent = str;
    return t;
  }
  function show(node, on) {
    node.setAttribute("opacity", on ? "1" : "0");
  }
  function place(node, x, y) {
    node.style.transform = "translate(" + x + "px," + y + "px)";
  }
  function setLine(node, x1, y1, x2, y2) {
    node.setAttribute("x1", x1);
    node.setAttribute("y1", y1);
    node.setAttribute("x2", x2);
    node.setAttribute("y2", y2);
  }
  function lerp(a, b, e) {
    return a + (b - a) * e;
  }
  function round1(v) {
    return (Math.round(v * 10) / 10).toFixed(1);
  }

  // Eased animation. fn(e) is called with e from 0 to 1. Without
  // requestAnimationFrame (or with ms = 0) it jumps straight to fn(1).
  var animTokens = {};
  function anim(key, ms, fn) {
    var token = (animTokens[key] || 0) + 1;
    animTokens[key] = token;
    if (typeof requestAnimationFrame !== "function" || ms <= 0) {
      fn(1);
      return;
    }
    var start = null;
    function frame(now) {
      if (animTokens[key] !== token) return;
      if (start === null) start = now;
      var p = Math.min(1, (now - start) / ms);
      var e = p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
      fn(e);
      if (p < 1) requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  }

  // Arrowheads, one marker per colour.
  var COLORS = { g: "#1DB584", y: "#E2B44A", p: "#F472B6", b: "#38BDF8", w: "#c9dccf", r: "#F87171" };
  var defs = el("defs", {}, svg);
  Object.keys(COLORS).forEach(function (k) {
    var m = el("marker", { id: "ah-" + k, viewBox: "0 0 10 10", refX: 9, refY: 5, markerUnits: "userSpaceOnUse", markerWidth: 13, markerHeight: 13, orient: "auto" }, defs);
    el("path", { d: "M0 0 L10 5 L0 10 Z", fill: COLORS[k] }, m);
  });
  function arrow(parent, colorKey, width) {
    return el("line", { x1: 0, y1: 0, x2: 0, y2: 0, stroke: COLORS[colorKey], "stroke-width": width || 3, "marker-end": "url(#ah-" + colorKey + ")", "stroke-linecap": "round" }, parent);
  }
  function polygon(parent, cls) {
    return el("polygon", { points: "", class: cls }, parent);
  }
  function setPoly(node, pts) {
    node.setAttribute("points", pts.map(function (p) { return p[0].toFixed(1) + "," + p[1].toFixed(1); }).join(" "));
  }
  function lerpPts(a, b, e) {
    return a.map(function (p, i) { return [lerp(p[0], b[i][0], e), lerp(p[1], b[i][1], e)]; });
  }
  // Maps maths coordinates (x right, y up) to screen pixels.
  function makePlane(cx, cy, s) {
    return {
      x: function (v) { return cx + s * v; },
      y: function (v) { return cy - s * v; },
      pt: function (p) { return [cx + s * p[0], cy - s * p[1]]; },
      s: s, cx: cx, cy: cy
    };
  }
  function axes(parent, plane, xr, yr) {
    el("line", { x1: plane.x(-xr), y1: plane.y(0), x2: plane.x(xr), y2: plane.y(0), class: "axis" }, parent);
    el("line", { x1: plane.x(0), y1: plane.y(-yr), x2: plane.x(0), y2: plane.y(yr), class: "axis" }, parent);
  }

  var EXPLAIN = {"original-space":{"h":"WHAT YOU ARE LOOKING AT","t":"A ring of **arrows pointing in many directions**, all the same length. We will see what a matrix **does to every one of them**."},"transform":{"h":"APPLY A MATRIX A","t":"The matrix **A** transforms every vector. It can change both its **direction and its length**, so the new, coloured arrows differ from the gray originals."},"most-vectors-turn":{"h":"MOST VECTORS TURN","t":"Compare each arrow before and after. For almost every vector the **direction has turned**: the coloured arrow no longer lies along its gray original."},"special-direction":{"h":"A FEW DIRECTIONS STAY PUT","t":"But along **two special lines** the transformed vector lands on the **same line it started on**. These are the directions the matrix treats most simply."},"eigenvector":{"h":"THESE ARE THE EIGENVECTORS","t":"A vector that **keeps its direction** under A is an **eigenvector**. It is only stretched, shrunk or flipped, never turned."},"eigenvalue":{"h":"THE SCALING FACTOR IS THE EIGENVALUE","t":"**A v = λ v.** Along **[1, 1]** the stretch is **λ = 3**, and along **[1, −1]** it is **λ = 1**. The eigenvalue says how much its eigenvector is stretched."},"ml-connection":{"h":"TAKEAWAY","t":"For a data covariance matrix, the eigenvectors point along the **main directions of the data**, and the eigenvalues say how much spread lies along each. **PCA uses exactly these.**"}};
  // ── scene ──
  var steps = [
    { id: "original-space", label: "Vectors in every direction", caption: "Start with vectors pointing in many directions, all the same length." },
    { id: "transform", label: "Apply a matrix A", caption: "A matrix A transforms every vector: it can change both its direction and its length." },
    { id: "most-vectors-turn", label: "Most vectors change direction", caption: "Compare each arrow before and after. For almost every vector, the direction has turned." },
    { id: "special-direction", label: "A few directions stay put", caption: "But along two special lines, the transformed vector lands on the same line it started on." },
    { id: "eigenvector", label: "These are the eigenvectors", caption: "A vector that keeps its direction under A is an eigenvector. It is only stretched, shrunk or flipped." },
    { id: "eigenvalue", label: "The scaling factor is the eigenvalue", caption: "A v = λ v. Along [1, 1] the stretch is λ = 3, and along [1, −1] it is λ = 1." },
    { id: "ml-connection", label: "Eigenvectors are the main directions", caption: "For a data covariance matrix, the eigenvectors point along the main directions of the data. PCA uses exactly these." }
  ];

  var P = makePlane(320, 190, 44);
  var M = [[2, 1], [1, 2]];
  function applyM(v) { return [M[0][0] * v[0] + M[0][1] * v[1], M[1][0] * v[0] + M[1][1] * v[1]]; }
  var R = 1.4;

  axes(svg, P, 6.5, 4.1);
  var cloud = el("ellipse", { cx: P.x(0), cy: P.y(0), rx: 4.2 * 44 * 0.8, ry: 1.2 * 44 * 0.8, class: "fillG", opacity: 0, transform: "rotate(-45 " + P.x(0) + " " + P.y(0) + ")" }, svg);

  // Two special lines (the eigen-directions).
  var lineA = el("line", { x1: P.x(-4.2), y1: P.y(-4.2), x2: P.x(4.2), y2: P.y(4.2), stroke: "#e2b44a", "stroke-width": 1.5, class: "dash", opacity: 0 }, svg);
  var lineB = el("line", { x1: P.x(-3.2), y1: P.y(3.2), x2: P.x(3.2), y2: P.y(-3.2), stroke: "#f472b6", "stroke-width": 1.5, class: "dash", opacity: 0 }, svg);

  var vecs = [];
  for (var k = 0; k < 12; k++) {
    var ang = ((45 + 30 * k) * Math.PI) / 180;
    var v = [R * Math.cos(ang), R * Math.sin(ang)];
    var special = k % 3 === 0; // 45°, 135°, 225°, 315°
    var orig = el("line", { stroke: "#8fa89c", "stroke-width": 2, "stroke-linecap": "round" }, svg);
    var out = arrow(svg, special ? (k === 0 || k === 6 ? "y" : "p") : "b", special ? 4 : 2.5);
    vecs.push({ v: v, Av: applyM(v), orig: orig, out: out, special: special, k: k });
  }

  function drawVectors(t) {
    vecs.forEach(function (o) {
      var tip = [lerp(o.v[0], o.Av[0], t), lerp(o.v[1], o.Av[1], t)];
      setLine(o.out, P.x(0), P.y(0), P.x(tip[0]), P.y(tip[1]));
      setLine(o.orig, P.x(0), P.y(0), P.x(o.v[0]), P.y(o.v[1]));
    });
  }

  var tagA = txt(svg, P.x(3.1), P.y(2.2), "lbl lbl-y", "", "start");
  var tagB = txt(svg, P.x(1.5), P.y(-3.7), "lbl lbl-p", "", "start");
  var turnNote = txt(svg, 40, 44, "lbl lbl-b", "", "start");
  var cloudNote = txt(svg, 40, 44, "lbl lbl-g", "", "start");
  var cloudNote2 = txt(svg, 40, 64, "note", "", "start");

  var tState = 0;
  function moveTo(target, ms) {
    var from = tState;
    anim("t", ms, function (e) { tState = lerp(from, target, e); drawVectors(tState); });
  }

  function render(index, id) {
    tagA.textContent = ""; tagB.textContent = ""; turnNote.textContent = ""; cloudNote.textContent = ""; cloudNote2.textContent = "";
    show(lineA, false); show(lineB, false); show(cloud, false);
    vecs.forEach(function (o) { show(o.out, true); show(o.orig, true); });

    if (id === "original-space") {
      moveTo(0, 300);
      vecs.forEach(function (o) { show(o.out, false); });
    } else if (id === "transform") {
      moveTo(1, 1000);
      vecs.forEach(function (o) { show(o.orig, true); o.orig.setAttribute("opacity", 0.35); });
    } else if (id === "most-vectors-turn") {
      moveTo(1, 200);
      vecs.forEach(function (o) { o.orig.setAttribute("opacity", 0.55); });
      turnNote.textContent = "gray = before A, colour = after A: most arrows turn";
    } else if (id === "special-direction") {
      moveTo(1, 200);
      show(lineA, true); show(lineB, true);
      vecs.forEach(function (o) { if (!o.special) { show(o.out, false); show(o.orig, false); } });
    } else if (id === "eigenvector") {
      moveTo(1, 200);
      show(lineA, true); show(lineB, true);
      vecs.forEach(function (o) { if (!o.special) { show(o.out, false); show(o.orig, false); } });
      tagA.textContent = "eigenvector [1, 1]";
      tagB.textContent = "eigenvector [1, −1]";
    } else if (id === "eigenvalue") {
      moveTo(1, 200);
      show(lineA, true); show(lineB, true);
      vecs.forEach(function (o) { if (!o.special) { show(o.out, false); show(o.orig, false); } });
      tagA.textContent = "A v = 3 v   (λ = 3)";
      tagB.textContent = "A w = 1 w   (λ = 1)";
    } else {
      moveTo(1, 200);
      show(cloud, true); show(lineA, true); show(lineB, true);
      vecs.forEach(function (o) { if (!o.special) { show(o.out, false); show(o.orig, false); } else show(o.orig, false); });
      cloudNote.textContent = "data cloud";
      cloudNote2.textContent = "its eigenvectors mark the main directions of spread";
    }
  }


  // ── shared runtime: stepping, explanation panel, educational autoplay pacing, bridge ──
  var current = 0;
  var explainHeadEl = document.getElementById("explain-h");

  // **bold** markers in an explanation become <strong> nodes (built with DOM calls, never innerHTML).
  function setRich(node, str) {
    node.textContent = "";
    var parts = String(str).split("**");
    for (var i = 0; i < parts.length; i++) {
      if (parts[i] === "") continue;
      var seg = document.createElement(i % 2 ? "strong" : "span");
      seg.textContent = parts[i];
      node.appendChild(seg);
    }
  }

  function explanationFor(index) {
    var ex = (typeof EXPLAIN === "object" && EXPLAIN) ? EXPLAIN[steps[index].id] : null;
    return ex || { h: "WHAT IS HAPPENING", t: steps[index].caption };
  }

  // Autoplay pace: 4.5 to 10.5 seconds per step, longer for longer explanations, so a learner can read.
  function stepMs(index) {
    var words = String(explanationFor(index).t).replace(/\*\*/g, "").split(/\s+/).length;
    return Math.max(4500, Math.min(10500, Math.round(3800 + words * 165)));
  }

  function renderStep(index) {
    var ex = explanationFor(index);
    labelEl.textContent = steps[index].label;
    if (explainHeadEl) explainHeadEl.textContent = ex.h;
    setRich(captionEl, ex.t);
    render(index, steps[index].id);
  }

  function goTo(index) {
    if (index < 0 || index >= steps.length) return;
    current = index;
    renderStep(current);
    if (window.ReagvisBridge) window.ReagvisBridge.stepChanged(steps[current].id);
  }

  renderStep(current);

  // Autoplay: exactly one timer, one step per tick, stops on the final step.
  // PLAY on the final step restarts from the first step and plays again.
  var timer = null;

  function stopAuto() {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
  }

  function scheduleNext() {
    timer = setTimeout(function () {
      timer = null;
      if (current >= steps.length - 1) return;
      goTo(current + 1);
      if (current < steps.length - 1) scheduleNext();
    }, stepMs(current));
  }

  function startAuto() {
    if (timer !== null) return;
    if (current >= steps.length - 1) goTo(0);
    scheduleNext();
  }

  window.addEventListener("pagehide", stopAuto);

  window.ReagvisAnimation = {
    stepDuration: stepMs,
    onCommand: function (type, stepId) {
      if (type === "PLAY") startAuto();
      else if (type === "PAUSE") stopAuto();
      else if (type === "NEXT") { stopAuto(); goTo(current + 1); }
      else if (type === "PREVIOUS") { stopAuto(); goTo(current - 1); }
      else if (type === "RESET") { stopAuto(); goTo(0); }
      else if (type === "GOTO_STEP") {
        stopAuto();
        for (var i = 0; i < steps.length; i++) {
          if (steps[i].id === stepId) { goTo(i); break; }
        }
      }
    },
  };

  if (window.ReagvisBridge) {
    window.ReagvisBridge.ready();
    window.ReagvisBridge.stepChanged(steps[current].id);
  }
})();
